add_filter( 'woocommerce_customer_get_downloadable_products', 'perfectpixel_extra_download_for_customers' );

function perfectpixel_extra_download_for_customers( $downloads ) {
	$attachment_id = (int) '{{extra_download_attachment_id}}';
	$url           = $attachment_id ? wp_get_attachment_url( $attachment_id ) : '';
	if ( ! $url ) {
		return $downloads;
	}
	$downloads[] = array(
		'download_url'        => $url,
		'download_id'         => 'perfectpixel-extra-' . $attachment_id,
		'product_id'          => 0,
		'product_name'        => '{{extra_download_title}}',
		'product_url'         => '',
		'download_name'       => basename( get_attached_file( $attachment_id ) ),
		'order_id'            => 0,
		'order_key'           => '',
		'downloads_remaining' => '',
		'access_expires'      => null,
		'file'                => array(
			'name' => basename( get_attached_file( $attachment_id ) ),
			'file' => $url,
		),
	);
	return $downloads;
}
